#include "ui/SubspaceUiFramework.h"
namespace subspace {SubspaceUiTheme SubspaceUiTheme::Dark(){SubspaceUiTheme t;t.canvas={.004f,.012f,.018f,1};t.panel={.010f,.026f,.034f,.98f};t.raised={.018f,.050f,.064f,.98f};t.border={.08f,.28f,.34f,.72f};t.textPrimary={.82f,.92f,.94f,1};t.textSecondary={.48f,.66f,.70f,.92f};t.accent={.18f,.68f,.76f,1};t.valid={.28f,.88f,.50f,1};t.warning={.94f,.68f,.24f,1};t.error={.92f,.28f,.26f,1};t.authoring={.66f,.42f,.92f,1};return t;}SubspaceUiColor SubspaceUiTheme::StateColor(SubspaceUiState s)const{switch(s){case SubspaceUiState::Hover:return{accent.r*.75f,accent.g*.75f,accent.b*.75f,1};case SubspaceUiState::Pressed:return{accent.r*.55f,accent.g*.55f,accent.b*.55f,1};case SubspaceUiState::Selected:return accent;case SubspaceUiState::Disabled:return{textSecondary.r*.45f,textSecondary.g*.45f,textSecondary.b*.45f,.65f};case SubspaceUiState::Valid:return valid;case SubspaceUiState::Warning:return warning;case SubspaceUiState::Error:return error;case SubspaceUiState::Authoring:return authoring;default:return raised;}}void EditorHelpRegistry::Register(EditorHelpEntry e){entries_[e.id]=std::move(e);}const EditorHelpEntry*EditorHelpRegistry::Find(const std::string&id)const{auto i=entries_.find(id);return i==entries_.end()?nullptr:&i->second;}std::string EditorHelpRegistry::Tooltip(const std::string&id,bool d,const std::string&reason)const{const auto*e=Find(id);if(!e)return reason;std::string t=e->displayName;if(!e->shortDescription.empty())t+="\n"+e->shortDescription;if(d&&!e->detailedDescription.empty())t+="\n"+e->detailedDescription;if(!e->shortcut.empty())t+="\nShortcut: "+e->shortcut;if(!reason.empty())t+="\nUnavailable: "+reason;return t;}}
